import os
import json
from taf.selenium.mobile.core.exceptions import InvalidDeviceName, InvalidChromePreferences


class Device(object):

    CUSTOM_DEVICES = {
        'huawei mate 30 pro': {'width': 392, 'height': 800, 'pixel_ratio': 3.0,
                               'user_agent': 'Mozilla/5.0 (Linux; Android 10; Huawei Mate 30 Pro) '
                                             'AppleWebKit/537.36 (KHTML, like Gecko) '
                                             'Chrome/80.0.3987.99 Mobile Safari/537.36'},
        'one plus 8': {'width': 412, 'height': 915, 'pixel_ratio': 2.625,
                       'user_agent': 'Mozilla/5.0 (Linux; Android 10; IN2019) '
                                     'AppleWebKit/537.36 (KHTML, like Gecko) Chrome/80.0.3987.99 Mobile Safari/537.36'}
    }

    def _create_device(self, *args, **kwargs):
        pass

    def _get_custom_device_name_list(self):
        return self.CUSTOM_DEVICES.keys()


class CustomDeviceChrome(Device):

    DEFAULT_PREFERENCES_FILE = '/home/{user}/.config/google-chrome/Default/Preferences'

    def __init__(self, device_name, preferences_file=None):
        self._mobile_emulation = None
        self._preferences_file = preferences_file
        self._create_device(device_name.lower())

    @property
    def mobile_emulation(self):
        return self._mobile_emulation

    def _get_default_device_name_list(self):
        if self._preferences_file is None:
            user = os.popen('/usr/bin/whoami').read().strip()
            self._preferences_file = self.DEFAULT_PREFERENCES_FILE.format(user=user)

        with open(self._preferences_file, 'rb') as json_file:
            json_string = json.load(json_file)

        try:
            emulated_device_list = json_string['devtools']['preferences']['standardEmulatedDeviceList']
            emulated_device_list = json.loads(emulated_device_list)
        except KeyError:
            raise InvalidChromePreferences('Re-install and run Chrome manually,'
                                           'then open Chrome devtools with "Ctrl+Shift+I".')

        default_emulated_device_list = []
        check_default_emulated_device_list = []
        for device in emulated_device_list:
            device_name = str(device['title'])
            default_emulated_device_list.append(device_name)
            check_default_emulated_device_list.append(device_name.lower())
        return default_emulated_device_list, check_default_emulated_device_list

    def _create_device(self, device_name):
        default_emulated_device_list, check_default_emulated_device_list = self._get_default_device_name_list()
        custom_device_list = self._get_custom_device_name_list()
        if device_name in check_default_emulated_device_list:
            for device in default_emulated_device_list:
                if device.lower() == device_name:
                    self._mobile_emulation = {'deviceName': device}
        elif device_name in custom_device_list:
            device_params = self.CUSTOM_DEVICES[device_name]
            self._mobile_emulation = {"deviceMetrics": {"width": device_params['width'],
                                                        "height": device_params['height'],
                                                        "pixelRatio": device_params['pixel_ratio']},
                                      "userAgent": device_params['user_agent']}
        else:
            device_list = list(custom_device_list) + default_emulated_device_list
            raise InvalidDeviceName(device_name, device_list)


class CustomDeviceFirefox(Device):

    def __init__(self, device_name):
        self._device = None
        self._create_device(device_name.lower())

    @property
    def width(self):
        return self._device['width']

    @property
    def height(self):
        return self._device['height']

    @property
    def user_agent(self):
        return self._device['user_agent']

    def _create_device(self, device_name):
        device_list = self._get_custom_device_name_list()
        if device_name in device_list:
            self._device = self.CUSTOM_DEVICES[device_name]
        else:
            raise InvalidDeviceName(device_name, device_list)
